referenceSolutions.python:
def risingLabelsBossReceipt(readings, k):
    a=readings
    out=[]
    from bisect import bisect_left
    tails=[]
    for x in a:
        i=bisect_left(tails,x)
        if i==len(tails): tails.append(x)
        else: tails[i]=x
        out.append(i+1)
    return sum((i+1)*x for i,x in enumerate(out))

